import numpy as np
def build(w):
    C=np.cos(w*t); S=np.sin(w*t)
    base=[np.ones_like(x),x,v,x*x,v*v,np.sin(v),np.exp(-v),1/v,np.sqrt(x)]
    cols=base+[b*C for b in [np.ones_like(x),x,v]]+[b*S for b in [np.ones_like(x),x,v]]
    return np.column_stack(cols)
def err(w):
    A=build(w); c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
    return np.mean((A@c-dv_dt)**2)/np.var(dv_dt), c
ws=np.linspace(0.05,8,1600)
E=np.array([err(w)[0] for w in ws])
idx=np.argsort(E)[:5]
for i in idx: print(ws[i],E[i])

